const p = $input.item.json;

const typPojazdu = (p.typ_pojazdu || 'osobowe').toLowerCase();
const pakiet = (p.pakiet || 'standard').toLowerCase();
const stanPojazdu = (p.stan_pojazdu || 'standardowy').toLowerCase();
const siersc = !!p.siersc_zwierzat;
const ozonowanie = !!p.ozonowanie;
const zabezpieczenie = !!p.zabezpieczenie_skory_tapicerki;

const BASE_BY_PACKAGE = { mycie: 100, standard: 250, pelny: 600, ceramika: 1500 };
const VEHICLE_MULTIPLIER = { osobowe: 1.0, suv_kombi: 1.25, van_dostawczy: 1.5 };

const baza = BASE_BY_PACKAGE[pakiet] !== undefined ? BASE_BY_PACKAGE[pakiet] : BASE_BY_PACKAGE.standard;
const mnoznik = VEHICLE_MULTIPLIER[typPojazdu] !== undefined ? VEHICLE_MULTIPLIER[typPojazdu] : VEHICLE_MULTIPLIER.osobowe;

const cena = baza * mnoznik;

let doplaty = 0;
let doplataZabrudzenie = 0;
if (stanPojazdu === 'mocno_zabrudzony') {
  doplataZabrudzenie = Math.round(cena * 0.3);
  doplaty += doplataZabrudzenie;
}
if (siersc) doplaty += 80;
if (ozonowanie) doplaty += 100;
if (zabezpieczenie) doplaty += 150;

const suma = cena + doplaty;
const min = Math.round(suma * 0.9);
const max = Math.round(suma * 1.15);

const skladniki = [];
skladniki.push('pakiet "' + pakiet + '" dla pojazdu typu "' + typPojazdu + '": ' + Math.round(cena) + ' zl');
if (doplataZabrudzenie > 0) skladniki.push('mocne zabrudzenie: +' + doplataZabrudzenie + ' zl');
if (siersc) skladniki.push('usuwanie siersci zwierzat: +80 zl');
if (ozonowanie) skladniki.push('ozonowanie/dezynfekcja: +100 zl');
if (zabezpieczenie) skladniki.push('zabezpieczenie skory/tapicerki: +150 zl');

return 'WIDELKI CENOWE: ' + min + '-' + max + ' zl. Pakiet: ' + pakiet + ', typ pojazdu: ' + typPojazdu + '. Skladniki wyceny: ' + skladniki.join('; ') + '.';
